// AxISA v2.1 step 3 (see sw/regge_test.axasm and docs/ISA.md's REGGE
// section): bit-exact SPIN/MASS on real hadrons, NaN below the
// intercept, in-place operation, and per-instruction cycle counts.
// GENERATED by tools/gen_regge_test.py.
`timescale 1ns/1ps
`ifndef INSTR_HEX
`define INSTR_HEX "sw/regge_test.hex"
`endif

module tb_regge;
    reg clk, reset;
    integer errors;
    integer max_cycles;
    integer cycle_count;

    wire halted;
    wire [31:0] tohost_value;
    wire        bus_req, bus_mem_write, bus_mem_unsigned, bus_grant;
    wire [31:0] bus_addr, bus_write_data, bus_read_data;
    wire [1:0]  bus_mem_size;
    wire        uart_tx_valid;
    wire [7:0]  uart_tx_data;

    cpu_core #(.INSTR_MEM_WORDS(1024), .INSTR_INIT_FILE(`INSTR_HEX)) dut (
        .clk(clk), .reset(reset), .halted(halted), .tohost_value(tohost_value),
        .irq_in(1'b0),
        .bus_req(bus_req), .bus_addr(bus_addr), .bus_write_data(bus_write_data),
        .bus_mem_write(bus_mem_write), .bus_mem_size(bus_mem_size), .bus_mem_unsigned(bus_mem_unsigned),
        .bus_grant(1'b0), .bus_read_data(32'b0),
        .uart_tx_valid(uart_tx_valid), .uart_tx_data(uart_tx_data),
        .uart_rx_data_in(8'b0), .uart_rx_ready_in(1'b0), .uart_rx_ack()
    );

    always #5 clk = ~clk;

    // cycles each REGGE keeps is_regge high, split by kind
    integer cur, n_spin, n_mass, spin_cyc, mass_cyc, spin_bad, mass_bad;
    reg cur_mass;
    initial begin cur = 0; n_spin = 0; n_mass = 0; spin_cyc = -1; mass_cyc = -1; spin_bad = 0; mass_bad = 0; end
    always @(posedge clk) begin
        if (!reset && dut.is_regge) begin cur = cur + 1; cur_mass = dut.regge_funct[1]; end
        else if (cur != 0) begin
            if (cur_mass) begin
                n_mass = n_mass + 1;
                if (mass_cyc == -1) mass_cyc = cur; else if (cur != mass_cyc) mass_bad = mass_bad + 1;
            end else begin
                n_spin = n_spin + 1;
                if (spin_cyc == -1) spin_cyc = cur; else if (cur != spin_cyc) spin_bad = spin_bad + 1;
            end
            cur = 0;
        end
    end

    task check(input [31:0] got, input [31:0] expected, input [64*8-1:0] name);
        begin
            if (got !== expected) begin
                $display("FAIL: %0s got=%0d (0x%h) expected=%0d (0x%h)", name, got, got, expected, expected);
                errors = errors + 1;
            end else begin
                $display("PASS: %0s = %0d (0x%h)", name, got, got);
            end
        end
    endtask

    initial begin
        errors = 0;
        max_cycles = 3000;

        clk = 0;
        reset = 1;
        cycle_count = 0;
        @(posedge clk); @(posedge clk);
        reset = 0;

        while (!halted && cycle_count < max_cycles) begin
            @(posedge clk);
            cycle_count = cycle_count + 1;
        end

        if (!halted) begin
            $display("FAIL: core never halted within %0d cycles", max_cycles);
            errors = errors + 1;
        end else begin
            $display("Halted after %0d cycles. tohost=%0d", cycle_count, tohost_value);
            check(tohost_value, 32'h4044471E, "tohost: SPIN.M in place (nd == ns)");
            check(dut.dmem.mem[11'h100], 32'h3F853126, "rho(770)    -> J = 1");
            check(dut.dmem.mem[11'h101], 32'h40041A99, "a2(1320)    -> J = 2");
            check(dut.dmem.mem[11'h102], 32'h4044471E, "rho3(1690)  -> J = 3");
            check(dut.dmem.mem[11'h103], 32'h407EDC0A, "a4(1970)    -> J = 4");
            check(dut.dmem.mem[11'h104], 32'h3FC20DA6, "Delta(1232) -> J = 3/2");
            check(dut.dmem.mem[11'h105], 32'h4060277B, "Delta(1950) -> J = 7/2");
            check(dut.dmem.mem[11'h106], 32'h40AD76DF, "Delta(2420) -> J = 11/2");
            check(dut.dmem.mem[11'h107], 32'h3F3ECFA7, "J = 1 meson -> rho mass");
            check(dut.dmem.mem[11'h108], 32'h400F1BBD, "J = 5 meson -> rho5(2350)");
            check(dut.dmem.mem[11'h109], 32'h3F9CC471, "J = 3/2 baryon -> Delta(1232)");
            check(dut.dmem.mem[11'h10A], 32'h7FC00000, "J = 0 is below the intercept: no real mass (NaN)");
            check(n_spin, 8, "SPIN instructions timed");
            check(n_mass, 4, "MASS instructions timed");
            check(spin_cyc, 6, "SPIN takes 6 cycles");
            check(spin_bad + mass_bad, 0, "every SPIN / every MASS takes the same time");
            check(mass_cyc > spin_cyc, 1, "MASS (with the sqrt) is slower than SPIN");
        end

        if (errors == 0) $display("ALL AXISA REGGE TESTS PASSED");
        else $display("%0d AXISA REGGE TEST(S) FAILED", errors);
        $finish;
    end
endmodule
